-- ============================================================
-- Concurso de disfraces de Halloween
-- Base de datos: `halloween`
--
-- Cómo importarlo: phpMyAdmin > pestaña "Importar" > elegir este archivo > "Importar".
-- El script crea la base si no existe. ATENCIÓN: si las tablas ya existen,
-- las borra y las vuelve a crear con los datos de ejemplo.
--
-- Las columnas de las tres tablas son exactamente las de la consigna.
-- Solo se agregan claves primarias, AUTO_INCREMENT, índices únicos y claves foráneas.
--
-- Usuarios de prueba:
--   admin / Halloween2026   (administrador, ver api/src/config.php)
--   lucia, mateo, sofia, tomas / calabaza2026
-- ============================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "-03:00";
SET NAMES utf8mb4;

CREATE DATABASE IF NOT EXISTS `halloween` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `halloween`;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS `votos`;
DROP TABLE IF EXISTS `disfraces`;
DROP TABLE IF EXISTS `usuarios`;
SET FOREIGN_KEY_CHECKS = 1;

-- --------------------------------------------------------
-- Estructura de tabla para la tabla `disfraces`
-- `foto` guarda el tipo MIME de la imagen (por ejemplo image/jpeg)
-- y `foto_blob` los bytes de la imagen (máximo 64 KB, el límite de BLOB).
-- --------------------------------------------------------

CREATE TABLE `disfraces` (
  `id` int(11) NOT NULL,
  `nombre` varchar(50) NOT NULL,
  `descripcion` text NOT NULL,
  `votos` int(11) NOT NULL,
  `foto` varchar(20) NOT NULL,
  `foto_blob` blob NOT NULL,
  `eliminado` int(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------
-- Estructura de tabla para la tabla `usuarios`
-- `clave` guarda el hash de password_hash(), nunca la contraseña.
-- --------------------------------------------------------

CREATE TABLE `usuarios` (
  `id` int(11) NOT NULL,
  `nombre` varchar(50) NOT NULL,
  `clave` text NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------
-- Estructura de tabla para la tabla `votos`
-- --------------------------------------------------------

CREATE TABLE `votos` (
  `id` int(11) NOT NULL,
  `id_usuario` int(11) NOT NULL,
  `id_disfraz` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

