INSERT INTO `disfraces` (`id`, `nombre`, `descripcion`, `votos`, `foto`, `foto_blob`, `eliminado`) VALUES (4, 'Esqueleto que brilla', 'Huesos pintados con pintura fluorescente sobre un jogging negro. Con la luz apagada parezco una radiografía.', 1, 'image/jpeg', , 0);
