-- --------------------------------------------------------
-- Índices
-- --------------------------------------------------------

ALTER TABLE `disfraces`
  ADD PRIMARY KEY (`id`),
  ADD KEY `idx_disfraces_eliminado_votos` (`eliminado`, `votos`);

-- Un nombre de usuario no se puede repetir (la comparación no distingue mayúsculas).
ALTER TABLE `usuarios`
  ADD PRIMARY KEY (`id`),
  ADD UNIQUE KEY `uq_usuarios_nombre` (`nombre`);

-- Un usuario puede votar cada disfraz una sola vez: la base rechaza el duplicado
-- aunque alguien llame a la API directamente.
ALTER TABLE `votos`
  ADD PRIMARY KEY (`id`),
  ADD UNIQUE KEY `uq_votos_usuario_disfraz` (`id_usuario`, `id_disfraz`),
  ADD KEY `idx_votos_disfraz` (`id_disfraz`);

-- --------------------------------------------------------
-- AUTO_INCREMENT
-- --------------------------------------------------------

ALTER TABLE `disfraces`
  MODIFY `id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=7;

ALTER TABLE `usuarios`
  MODIFY `id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=6;

ALTER TABLE `votos`
  MODIFY `id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=13;

-- --------------------------------------------------------
-- Claves foráneas
-- --------------------------------------------------------

ALTER TABLE `votos`
  ADD CONSTRAINT `fk_votos_usuario` FOREIGN KEY (`id_usuario`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE,
  ADD CONSTRAINT `fk_votos_disfraz` FOREIGN KEY (`id_disfraz`) REFERENCES `disfraces` (`id`) ON DELETE CASCADE;
